const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(d,opts)=>new Intl.DateTimeFormat('cs-CZ',{timeZone:'Europe/Prague',...opts}).format(new Date(d));
const key='vitkovice-vip-kiosk-v1';
let state={entries:[],results:{}};
try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&Array.isArray(saved.entries)&&saved.results&&typeof saved.results==='object')state=saved}catch{}
let currentId=matches.find(m=>new Date(m.date)>new Date())?.id||matches.at(-1).id;
let outcome='',screen='welcome',timer,lastActivity=Date.now();
const current=()=>matches.find(m=>m.id===currentId);
const open=m=>Date.now()<new Date(m.date).getTime()&&!state.results[m.id];
const entries=id=>state.entries.filter(e=>e.matchId===id);
function persist(next){try{localStorage.setItem(key,JSON.stringify(next));state=next;return true}catch{message('Uložení se nezdařilo. Požádej obsluhu o pomoc.');return false}}
function message(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',5000)}
function matchLine(m){return `Vítkovice Ridera <span class="versus">vs.</span> ${esc(m.opponent)}`}
function selectMatch(){return `<label class="field-label" for="match">Domácí zápas</label><select id="match">${matches.map(m=>`<option value="${m.id}" ${m.id===currentId?'selected':''}>${fmt(m.date,{day:'numeric',month:'numeric',hour:'2-digit',minute:'2-digit'})} · ${esc(m.opponent)}${open(m)?'':' · uzavřeno'}</option>`).join('')}</select>`}
function winnersMarkup(m){const result=state.results[m.id];if(!result)return '<p>Výsledek zatím není potvrzený. Po vyhodnocení zde vyhlásíme vítěze.</p>';const winners=Competition.evaluate(entries(m.id),result);return `<div class="final-score">${result.home} : ${result.away}</div><p>Výsledek po 60 minutách</p>${winners.length?`<span class="eyebrow">${winners[0].distance===0?'PŘESNÝ TIP':'NEJBLIŽŠÍ TIP'}</span><h1>${winners.length===1?'Gratulujeme vítězi!':'Gratulujeme vítězům!'}</h1><div class="winner-names">${winners.map(e=>`<div>${esc(e.name)} <small>tip ${e.home} : ${e.away}</small></div>`).join('')}</div><p class="prize">Cenu si vyzvedněte ve VIP zóně.</p>`:'<h1>Tento zápas nemá žádné tipy.</h1>'}`}
function welcome(){screen='welcome';outcome='';$('#main').innerHTML=`<section class="attract"><img class="attract-logo" src="${logo}" alt="HC Vítkovice Ridera"><span class="eyebrow">EXKLUZIVNĚ PRO HOSTY VIP ZÓNY</span><h1>Na ledě tým.<br>Ve hře ty.</h1><p>Tipni skóre. Užij si zápas. Vyhraj cenu.</p><div class="attract-match">${matchLine(current())}<small>${fmt(current().date,{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'})} · základní hrací doba</small></div><button class="touch-start" data-action="start">☝ <span>Dotkni se obrazovky<small>a zapoj se do tipovací soutěže</small></span> →</button><button class="text-button" data-action="winners">Výsledky a vítězové →</button><div class="attract-bottom">JEDEN TÝM. JEDNO SRDCE. <span>HC VÍTKOVICE RIDERA</span></div></section>`}
function form(){screen='form';outcome='';const m=current();$('#main').innerHTML=`<div class="kiosk-head"><button class="text-button" data-action="home">← Úvod</button><span class="eyebrow">VIP TIPOVACÍ SOUTĚŽ</span><button class="text-button" data-action="rules">Pravidla</button></div><section class="kiosk-card"><span class="eyebrow">${open(m)?'TVŮJ TIP NA DOMÁCÍ ZÁPAS':'TIPOVÁNÍ UZAVŘENO'}</span><h1>${matchLine(m)}</h1><p class="hint">${fmt(m.date,{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'})} · Tipujeme po 60 minutách, bez prodloužení a nájezdů.</p>${selectMatch()}${!open(m)?'<div class="notice">Tento zápas už nelze tipovat. Vyber další domácí utkání nebo se podívej na vítěze.</div><button class="primary" data-action="winners">Výsledky a vítězové →</button>':`<form id="entry-form" autocomplete="off"><label class="field-label" for="guest-name">1. Jak se jmenuješ?</label><input id="guest-name" name="name" type="text" minlength="2" maxlength="60" required autocomplete="off" placeholder="Tvé jméno a příjmení"><label class="field-label">2. Jak zápas dopadne?</label><div class="choices">${[['1','Vyhrají Vítkovice'],['X','Remíza'],['2','Vyhrají hosté']].map(([v,label])=>`<button type="button" data-outcome="${v}" class="choice" aria-pressed="false"><b>${v}</b>${label}</button>`).join('')}</div><div class="form-row"><div><label class="field-label" for="home-score">3. Tipni přesné skóre</label><div class="score"><div><input id="home-score" aria-label="Góly Vítkovic" type="number" inputmode="numeric" min="0" max="30" required placeholder="0"><small>Vítkovice</small></div><span>:</span><div><input id="away-score" aria-label="Góly soupeře" type="number" inputmode="numeric" min="0" max="30" required placeholder="0"><small>Hosté</small></div></div></div><div><label class="field-label" for="goals">4. Kolik padne gólů? <small>(volitelné)</small></label><select id="goals"><option value="">Bez dalšího tipu</option><option value="under">0 až 5 gólů (pod 5,5)</option><option value="over">6 a více gólů (nad 5,5)</option></select></div></div><p class="hint">Jméno použijeme k vyhlášení vítěze na této obrazovce. Jeden tip na jméno a zápas na tomto kiosku. Při shodě vyhrávají všichni stejně úspěšní.</p><div class="submit-row"><button type="button" class="text-button" data-action="rules">Jak vybíráme vítěze?</button><button class="primary">Potvrdit můj tip →</button></div></form>`}</section>`}
function resultScreen(){screen='winners';const m=current();$('#main').innerHTML=`<div class="kiosk-head"><button class="text-button" data-action="home">← Úvod</button><span class="eyebrow">VIP TIPOVACÍ SOUTĚŽ</span><button class="text-button" data-action="rules">Pravidla</button></div><section class="kiosk-card results-screen">${selectMatch()}<h2>${matchLine(m)}</h2>${winnersMarkup(m)}<button class="primary" data-action="home">Zpět na úvod →</button></section>`}
function thanks(entry){screen='thanks';$('#main').innerHTML=`<section class="attract confirmation"><span class="confirmation-icon">✓</span><span class="eyebrow">TIP JE ULOŽENÝ</span><h1>Díky za tip,<br>${esc(entry.name)}!</h1><p>${matchLine(current())}</p><div class="final-score">${entry.home} : ${entry.away}</div><p>Po zápase vyhlásíme vítěze.<br>Cenu si vítěz vyzvedne ve VIP zóně.</p><button class="touch-start" data-action="home">Další návštěvník →</button><small>Za 12 sekund se obrazovka vrátí na úvod.</small></section>`;setTimeout(()=>{if(screen==='thanks')welcome()},12000)}
function rules(){ $('#dialog-content').innerHTML='<span class="eyebrow">PRAVIDLA VIP SOUTĚŽE</span><h1>Jak vybereme vítěze?</h1><ol><li>Vyber výsledek 1 / X / 2 a přesné skóre po 60 minutách. Remíza je platný tip.</li><li>Vyhrává přesné skóre. Pokud jej nikdo netrefí, vyhrává nejmenší součet odchylek obou skóre. Pro výsledek 2:1 má tip 3:1 odchylku 1.</li><li>Při stejné odchylce rozhodne správný doplňkový tip na počet gólů (0–5 / 6 a více). I mezi přesnými tipy.</li><li>Při další shodě vyhlašujeme všechny společné vítěze. Rozdělení cen zajistí obsluha VIP zóny.</li><li>Jeden tip na jméno a utkání na tomto zařízení. Tip nelze po potvrzení měnit. Jméno není ověřená totožnost.</li><li>Tipování končí v plánovaný začátek zápasu. Při odložení pořadatel musí termín nejprve opravit; automatické změny zatím nejsou připojené.</li></ol><p>Místní prototyp: tipy zůstávají v tomto prohlížeči. Výsledek ručně potvrzuje obsluha. Ceny a finální pravidla schvaluje pořadatel.</p>';$('#dialog').showModal()}
function staff(){screen='staff';const m=current();$('#main').innerHTML=`<div class="kiosk-head"><button class="text-button" data-action="home">← Kiosek</button><span class="eyebrow">OBSLUHA · MÍSTNÍ PROTOTYP</span></div><section class="kiosk-card"><h1>Vyhodnocení zápasu</h1><div class="notice">Tato místní administrace není chráněná přihlášením. Pro ostrý provoz je potřeba server a samostatný přístup obsluhy. Výsledek zadejte až po skončení základní hrací doby.</div>${selectMatch()}<p class="hint">${entries(m.id).length} přijatých tipů na tomto zařízení</p>${state.results[m.id]?`<h2>Potvrzený výsledek: ${state.results[m.id].home} : ${state.results[m.id].away}</h2><p class="hint">Výsledek je uzamčený. Vyhlášení vítězů najdete v kiosku.</p><button class="primary" data-action="winners">Zobrazit vítěze →</button>`:`<form id="result-form"><label class="field-label">Potvrzený výsledek po 60 minutách</label><div class="score"><input id="result-home" aria-label="Skutečné góly Vítkovic" type="number" min="0" max="30" inputmode="numeric" required><span>:</span><input id="result-away" aria-label="Skutečné góly soupeře" type="number" min="0" max="30" inputmode="numeric" required></div><label class="confirm-label"><input id="result-confirm" type="checkbox" required> Ověřil/a jsem výsledek po 60 minutách a chci vyhlásit vítěze.</label><button class="primary" ${Date.now()<new Date(m.date).getTime()?'disabled':''}>Potvrdit výsledek a vyhodnotit →</button><p class="hint">${Date.now()<new Date(m.date).getTime()?'Zápas ještě nezačal. Vyhodnocení je uzamčené.':'Výsledek potvrďte až po dohrání 60 minut.'}</p></form>`}</section>`}
function submitEntry(){const m=current();if(!open(m)){message('Tipování je už uzavřené.');form();return}const h=$('#home-score').value,a=$('#away-score').value;const entry={id:crypto.randomUUID(),matchId:m.id,name:$('#guest-name').value.trim().replace(/\s+/g,' '),outcome,home:h===''?null:Number(h),away:a===''?null:Number(a),goals:$('#goals').value,savedAt:new Date().toISOString()};const error=Competition.validate(entry);if(error){message(error);return}const normalized=s=>s.normalize('NFKC').toLocaleLowerCase('cs-CZ');if(entries(m.id).some(e=>normalized(e.name)===normalized(entry.name))){message('Na toto jméno už je pro tento zápas tip uložený. Při shodě jmen se obrať na obsluhu.');return}if(persist({...state,entries:[...state.entries,entry]}))thanks(entry)}
function submitResult(){const m=current();if(Date.now()<new Date(m.date).getTime()||state.results[m.id]){message('Tento zápas teď nelze vyhodnotit.');return}const h=$('#result-home').value,a=$('#result-away').value;const result={home:h===''?null:Number(h),away:a===''?null:Number(a),confirmedAt:new Date().toISOString()};if(!Competition.validScore(result.home)||!Competition.validScore(result.away)||!$('#result-confirm').checked){message('Vyplň skóre a potvrď ověření výsledku.');return}if(persist({...state,results:{...state.results,[m.id]:result}}))resultScreen()}
function home(){lastActivity=Date.now();if($('#dialog').open)$('#dialog').close();if(location.hash)history.replaceState(null,'',location.pathname+location.search);welcome()}
$('#main').addEventListener('submit',event=>{event.preventDefault();if(event.target.id==='entry-form')submitEntry();if(event.target.id==='result-form')submitResult()});
$('#main').addEventListener('change',event=>{if(event.target.id==='match'){currentId=event.target.value;screen==='staff'?staff():screen==='winners'?resultScreen():form()}});
$('#main').addEventListener('click',event=>{const b=event.target.closest('[data-outcome]');if(b){outcome=b.dataset.outcome;document.querySelectorAll('[data-outcome]').forEach(el=>{el.classList.toggle('selected',el.dataset.outcome===outcome);el.setAttribute('aria-pressed',String(el.dataset.outcome===outcome))})}const action=event.target.closest('[data-action]')?.dataset.action;if(action==='start')form();if(action==='home')home();if(action==='winners')resultScreen();if(action==='rules')rules()});
$('#rules').onclick=rules;$('.close').onclick=()=>$('#dialog').close();
for(const type of ['pointerdown','keydown','input'])document.addEventListener(type,()=>lastActivity=Date.now());
setInterval(()=>{if(!['welcome','staff'].includes(screen)&&Date.now()-lastActivity>90000)home();if(screen==='form'&&!open(current())&&$('#entry-form'))form()},1000);
addEventListener('hashchange',()=>location.hash==='#obsluha'?staff():home());
location.hash==='#obsluha'?staff():welcome();
